11	/**
12	 * SIMULATED-PRICING-RULE-v1 (specs/US-02-plan-list.md, approved 2026-11-21).
13	 * Illustrative only — not an actuarial rating engine.
14	 */
15	export function applySimulatedPricingRule(
16	  basePrice: number,
17	  input: SimulatedPricingRuleInput,
18	  referenceDate: Date = new Date(),
19	): number {
20	  const factor =
21	    driverAgeFactor(input.dateOfBirth, referenceDate) *
22	    vehicleAgeFactor(input.vehicleYear, referenceDate.getFullYear()) *
23	    usageFactor(input.vehicleUsage);
24	
25	  return Math.round(basePrice * factor);
26	}
