80	  const dateOfBirth = step1['dateOfBirth'];
81	  const vehicleYear = step1['vehicleYear'];
82	  const vehicleUsage = step1['vehicleUsage'];
83	
84	  return {
85	    dateOfBirth: typeof dateOfBirth === 'string' && dateOfBirth !== '' ? dateOfBirth : null,
86	    vehicleYear: typeof vehicleYear === 'number' ? vehicleYear : null,
87	    vehicleUsage: vehicleUsage === 'personal' || vehicleUsage === 'commercial' ? vehicleUsage : null,
88	  };
