2	
3	function stripSeparators(value: string): string {
4	  return value.replace(/[.\-\s]/g, '');
5	}
6	
7	function isSeparator(char: string): boolean {
8	  return char === '.' || char === '-';
9	}
10	
11	function formatChileanRut(cleaned: string): string {
12	  if (cleaned.length <= 1) {
13	    return cleaned;
14	  }
15	
16	  const checkDigit = cleaned.slice(-1);
17	  const body = cleaned.slice(0, -1);
18	  const groups: string[] = [];
19	  for (let end = body.length; end > 0; end -= 3) {
20	    groups.unshift(body.slice(Math.max(0, end - 3), end));
21	  }
22	
23	  return groups.length > 0 ? `${groups.join('.')}-${checkDigit}` : checkDigit;
24	}
25	
26	function formatForCountry(cleaned: string, country: CountryCode): string {
27	  return country === 'CL' ? formatChileanRut(cleaned) : cleaned;
28	}
29	
30	/**
31	 * US-03 masking rule (specs/US-03-summary-payment.md, Resolutions): keeps the first 2 and
32	 * last 2 characters of the country-formatted display visible (only the last character for
33	 * a raw value of 4 characters or fewer), masks every other identifier character with "•",
34	 * and leaves grouping separators (".", "-") untouched so a CL RUT still reads as grouped.
35	 */
36	export function maskDocumentNumber(rawValue: string, country: CountryCode): string {
37	  const cleaned = stripSeparators(rawValue.trim());
38	  if (cleaned.length === 0) {
39	    return '';
40	  }
41	
42	  const display = formatForCountry(cleaned, country);
43	  const isShort = cleaned.length <= 4;
44	
45	  return Array.from(display)
46	    .map((char, index) => {
47	      if (isSeparator(char)) {
48	        return char;
49	      }
50	      const isVisible = isShort ? index === display.length - 1 : index < 2 || index >= display.length - 2;
51	      return isVisible ? char : '•';
52	    })
53	    .join('');
54	}
