30	    currency,
31	    maximumFractionDigits: 0,
32	  }).format(amount);
33	}
34	
35	@Component({
36	  selector: 'app-quote-summary-page',
37	  imports: [RouterLink],
38	  templateUrl: './quote-summary-page.component.html',
39	  styleUrl: './quote-summary-page.component.scss',
40	})
41	export class QuoteSummaryPageComponent {
42	  private readonly wizardStore = inject(WizardStore);
43	  private readonly countryContentService = inject(CountryContentService);
44	  private readonly countryStore = inject(CountryStore);
45	  private readonly simulatedPaymentService = inject(SimulatedPaymentService);
46	  private readonly router = inject(Router);
47	  private readonly destroyRef = inject(DestroyRef);
48	
49	  private readonly termsState = this.countryContentService.getTerms();
50	
51	  readonly country = this.countryStore.country;
52	  readonly policyholder = computed(() => projectReservedStep1Fields(this.wizardStore.state().step1.value));
53	  readonly plan = computed(() => this.wizardStore.state().selectedPlan);
54	
55	  readonly maskedDocumentNumber = computed(() => {
56	    const fields = this.policyholder();
57	    const country = this.country();
58	    return fields && country ? maskDocumentNumber(fields.documentNumber, country) : '';
59	  });
60	
61	  readonly formattedPrice = computed(() => {
62	    const plan = this.plan();
63	    const country = this.country();
64	    if (!plan || !country) {
65	      return '';
66	    }
67	    return formatPrice(plan.finalPrice, plan.currency, LOCALE_BY_COUNTRY[country]);
68	  });
69	
70	  readonly termsLoading = computed(() => this.termsState().loading);
71	  readonly termsError = computed(() => this.termsState().error);
72	  readonly termsContent = computed(() => this.termsState().data);
73	
74	  readonly isTermsAccepted = computed(() => {
75	    const terms = this.wizardStore.state().terms;
76	    const content = this.termsContent();
77	    return terms.accepted && content !== null && terms.acceptedVersion === content.version;
78	  });
79	
80	  readonly paymentStatus = computed(() => this.wizardStore.state().payment.status);
81	  private readonly paymentResult = computed(() => this.wizardStore.state().payment.result);
82	
83	  readonly isSubmitting = computed(() => this.paymentStatus() === 'submitting');
84	  readonly isApproved = computed(() => this.paymentStatus() === 'approved');
85	
86	  readonly approvedQuoteNumber = computed(() => {
87	    const result = this.paymentResult();
88	    return result?.status === 'approved' ? result.quoteNumber : null;
89	  });
90	
91	  readonly rejectedReason = computed(() => {
92	    const result = this.paymentResult();
93	    return result?.status === 'rejected' ? result.reason : null;
94	  });
95	
96	  readonly canPay = computed(
97	    () =>
98	      this.isTermsAccepted() &&
99	      !this.termsLoading() &&
100	      !this.termsError() &&
101	      this.paymentStatus() !== 'submitting' &&
102	      this.paymentStatus() !== 'approved',
103	  );
104	
105	  readonly confirmationPanel = viewChild<ElementRef<HTMLElement>>('confirmationPanel');
106	  readonly errorPanel = viewChild<ElementRef<HTMLElement>>('errorPanel');
107	
108	  constructor() {
109	    // A direct link to this step without completed prior steps never renders a broken
110	    // summary; once a payment is approved the screen is locked and this guard no longer
111	    // applies, since the data it would otherwise redirect for is still intact.
112	    effect(() => {
113	      const state = this.wizardStore.state();
114	      if (state.payment.status === 'approved') {
115	        return;
116	      }
117	      if (projectReservedStep1Fields(state.step1.value) === null) {
118	        this.router.navigate(['/quote/form']);
119	        return;
120	      }
121	      if (state.selectedPlan === null) {
122	        this.router.navigate(['/quote/plans']);
123	      }
124	    });
125	
126	    afterRenderEffect(() => {
127	      const status = this.paymentStatus();
128	      if (status === 'approved') {
129	        this.confirmationPanel()?.nativeElement.focus();
130	      } else if (status === 'rejected') {
131	        this.errorPanel()?.nativeElement.focus();
132	      }
133	    });
134	  }
135	
136	  onTermsCheckboxChange(checked: boolean): void {
137	    const content = this.termsContent();
138	    this.wizardStore.setTermsAccepted(checked, checked ? (content?.version ?? null) : null);
139	  }
140	
141	  retryTerms(): void {
142	    this.countryContentService.refetchTerms();
143	  }
144	
145	  pay(): void {
146	    if (!this.canPay()) {
147	      return;
148	    }
149	
150	    const plan = this.plan();
151	    const country = this.country();
152	    if (!plan || !country) {
153	      return;
154	    }
155	
156	    this.wizardStore.setPaymentStatus('submitting');
157	    this.wizardStore.setPaymentResult(null);
158	
159	    this.simulatedPaymentService
160	      .submitPayment({
161	        quoteDraftId: `${country}-${plan.id}`,
162	        amount: plan.finalPrice,
163	        currency: plan.currency,
164	        country,
165	      })
166	      .pipe(takeUntilDestroyed(this.destroyRef))
167	      .subscribe({
168	        next: (result) => {
169	          this.wizardStore.setPaymentResult(result);
170	          this.wizardStore.setPaymentStatus(result.status);
171	        },
172	        error: (error: unknown) => {
173	          console.error('Simulated payment request failed', error);
174	          this.wizardStore.setPaymentResult({
175	            status: 'rejected',
176	            reason: 'We could not process the payment. Please try again.',
177	          });
178	          this.wizardStore.setPaymentStatus('rejected');
179	        },
180	      });
181	  }
182	}
